static uint32_t decode_utf8(const char **src) {
    const uint8_t *s = (const uint8_t *)*src;
    uint32_t cp = 0;
    if (!*s) return 0;
    if (*s < 0x80) {
        cp = *s++;
    } else if ((*s & 0xE0) == 0xC0) {
        cp = (uint32_t)(*s++ & 0x1F) << 6;
        if ((*s & 0xC0) == 0x80) cp |= (*s++ & 0x3F);
    } else if ((*s & 0xF0) == 0xE0) {
        cp = (uint32_t)(*s++ & 0x0F) << 12;
        if ((*s & 0xC0) == 0x80) {
            cp |= (uint32_t)(*s++ & 0x3F) << 6;
            if ((*s & 0xC0) == 0x80) cp |= (*s++ & 0x3F);
        }
    } else if ((*s & 0xF8) == 0xF0) {
        cp = (uint32_t)(*s++ & 0x07) << 18;
        if ((*s & 0xC0) == 0x80) {
            cp |= (uint32_t)(*s++ & 0x3F) << 12;
            if ((*s & 0xC0) == 0x80) {
                cp |= (uint32_t)(*s++ & 0x3F) << 6;
                if ((*s & 0xC0) == 0x80) cp |= (*s++ & 0x3F);
            }
        }
    } else {
        s++;
    }
    *src = (const char *)s;
    return cp;
}

